package com.printflow.identity;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.util.*;import java.nio.charset.StandardCharsets;import jakarta.mail.*;import jakarta.mail.internet.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.mock.env.MockEnvironment;
class QuotationMailTest {
 final JdbcTemplate db=mock(JdbcTemplate.class);final String key=Base64.getEncoder().encodeToString(new byte[32]);final UUID lead=UUID.randomUUID(),quote=UUID.randomUUID();
 final CustomerMail mail=new CustomerMail(db,key,false,"smtp.gmail.com",587,"sender@example.test","private","http://127.0.0.1:3000","","",new MockEnvironment());
 Map<String,Object> row(){return new HashMap<>(Map.of("kind","QUOTE","payload",new MfaSecrets(key).encrypt("J.D.Printex\n\nReview <img src=x onerror=alert(1)> & approve.\n\nCustomer workspace: http://127.0.0.1:3000/customer"),"recipient","customer@example.test","quote_id",quote,"enquiry_id",lead,"subject","J.D.Printex | Wedding cards | PF-ABC12345","message_id","<quote-"+quote+"@jdprintex.in>","reply_to_id","<enquiry-"+lead+"@jdprintex.in>"));}
 Map<String,Object> document(byte[] bytes)throws Exception{return Map.of("document_pdf",bytes,"document_sha256",HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes)),"version",1,"total_paise",5900000,"delivery","31 Oct 2026","public_id",UUID.randomUUID());}
 void parts(Part part,List<Part> all)throws Exception{if(part.isMimeType("multipart/*")){Multipart m=(Multipart)part.getContent();for(int i=0;i<m.getCount();i++)parts(m.getBodyPart(i),all);}else all.add(part);}
 @Test void quotationHasExactPdfAccessibleAlternativesBrandAndThreadHeaders()throws Exception{
  byte[] bytes="%PDF-1.7 immutable version one".getBytes(StandardCharsets.UTF_8);when(db.queryForMap(anyString(),eq(quote),eq(lead))).thenReturn(document(bytes));MimeMessage message=mail.compose(row());List<Part> all=new ArrayList<>();parts(message,all);
  Part pdf=all.stream().filter(p->{try{return Part.ATTACHMENT.equals(p.getDisposition());}catch(Exception e){throw new RuntimeException(e);}}).findFirst().orElseThrow();assertArrayEquals(bytes,pdf.getInputStream().readAllBytes());assertTrue(pdf.getFileName().startsWith("J.D.Printex-Quotation-v1-PF-"));assertTrue(pdf.isMimeType("application/pdf"));
  Part plain=all.stream().filter(p->{try{return p.isMimeType("text/plain");}catch(Exception e){return false;}}).findFirst().orElseThrow(),html=all.stream().filter(p->{try{return p.isMimeType("text/html");}catch(Exception e){return false;}}).findFirst().orElseThrow();assertTrue(plain.getContent().toString().contains("/customer"));String content=html.getContent().toString();assertTrue(content.contains("Open customer workspace"));assertTrue(content.contains("Quotation v1"));assertTrue(content.contains("31 Oct 2026"));assertFalse(content.contains("<img src=x"));assertTrue(content.contains("&lt;img"));assertTrue(content.contains("href=\"http://127.0.0.1:3000/customer\""));assertEquals("J.D.Printex",((InternetAddress)message.getFrom()[0]).getPersonal());assertEquals("<quote-"+quote+"@jdprintex.in>",message.getMessageID());assertEquals("<enquiry-"+lead+"@jdprintex.in>",message.getHeader("In-Reply-To",null));verify(db).queryForMap(contains("q.id=? and q.enquiry_id=?"),eq(quote),eq(lead));
 }
 @Test void workThreadReferencesItsOwnRootAndFirstMessageHasNoReplyHeaders()throws Exception{byte[] bytes="%PDF-1.7".getBytes(StandardCharsets.UTF_8);when(db.queryForMap(anyString(),eq(quote),eq(lead))).thenReturn(document(bytes));var row=row();row.put("thread_root_id","<quote-root@jdprintex.in>");row.put("reply_to_id","<review-previous@jdprintex.in>");assertEquals("<quote-root@jdprintex.in> <review-previous@jdprintex.in>",mail.compose(row).getHeader("References",null));row.remove("reply_to_id");assertNull(mail.compose(row).getHeader("In-Reply-To",null));assertNull(mail.compose(row).getHeader("References",null));}
 @Test void artworkReviewAttachesOnlyItsVerifiedEnquiryCopy()throws Exception{UUID feedback=UUID.randomUUID();byte[] bytes="%PDF-1.7 annotated review".getBytes(StandardCharsets.UTF_8);var values=new HashMap<String,Object>();values.put("review_pdf",bytes);values.put("review_sha256",HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes)));when(db.queryForMap(anyString(),eq(feedback),eq(lead))).thenReturn(values);var r=row();r.put("kind","REFERENCE_REVIEW");r.put("feedback_id",feedback);List<Part> all=new ArrayList<>();parts(mail.compose(r),all);Part pdf=all.stream().filter(p->{try{return Part.ATTACHMENT.equals(p.getDisposition());}catch(Exception e){return false;}}).findFirst().orElseThrow();assertArrayEquals(bytes,pdf.getInputStream().readAllBytes());assertEquals("J.D.Printex-Artwork-review.pdf",pdf.getFileName());r.put("is_team",true);List<Part> teamParts=new ArrayList<>();parts(mail.compose(r),teamParts);String teamHtml=teamParts.stream().filter(p->{try{return p.isMimeType("text/html");}catch(Exception e){return false;}}).findFirst().orElseThrow().getContent().toString();assertTrue(teamHtml.contains("Open team workspace"));assertTrue(teamHtml.contains("href=\"http://127.0.0.1:3000/business\""));verify(db,times(2)).queryForMap(contains("id=? and enquiry_id=?"),eq(feedback),eq(lead));values.put("review_sha256","0".repeat(64));assertThrows(IllegalStateException.class,()->mail.compose(r));}
 @Test void absentOrTamperedIssuedDocumentCannotBecomeAnAttachment()throws Exception{var row=row();row.remove("quote_id");assertThrows(IllegalStateException.class,()->mail.compose(row));byte[] bytes="%PDF-1.7".getBytes(StandardCharsets.UTF_8);var bad=new HashMap<>(document(bytes));bad.put("document_sha256","0".repeat(64));when(db.queryForMap(anyString(),eq(quote),eq(lead))).thenReturn(bad);assertThrows(IllegalStateException.class,()->mail.compose(row()));}

 @Test void invoiceMailAttachesOnlyVerifiedImmutableDocument()throws Exception{byte[] bytes="%PDF-1.7 invoice fixture".getBytes(StandardCharsets.UTF_8);UUID invoice=UUID.randomUUID();var r=row();r.put("kind","INVOICE");r.put("invoice_id",invoice);var values=new HashMap<String,Object>();values.put("document_pdf",bytes);values.put("document_sha256",com.printflow.customer.Payments.sha(bytes));values.put("invoice_number",77);when(db.queryForMap(anyString(),eq(invoice),eq(lead))).thenReturn(values);List<Part> all=new ArrayList<>();parts(mail.compose(r),all);Part pdf=all.stream().filter(p->{try{return Part.ATTACHMENT.equals(p.getDisposition());}catch(Exception e){return false;}}).findFirst().orElseThrow();assertArrayEquals(bytes,pdf.getInputStream().readAllBytes());assertEquals("J.D.Printex-Invoice-INV-77.pdf",pdf.getFileName());values.put("document_sha256","0".repeat(64));assertThrows(IllegalStateException.class,()->mail.compose(r));}
 @Test void subjectIsReadableStableAndCannotInjectHeaders(){String ref=UUID.randomUUID().toString();String first=MailPresentation.subject("ENQUIRY",ref,"Wedding cards\r\nBcc: bad");assertFalse(first.contains("\r"));assertFalse(first.contains("\n"));assertFalse(first.contains(ref));assertTrue(first.contains("Wedding cards"));assertTrue(MailPresentation.subject("ENQUIRY",ref,"Shaadi & Wedding Cards").startsWith("Enquiry received — Wedding Cards"));assertNotEquals(MailPresentation.subject("INTAKE",ref,"Wedding cards"),MailPresentation.subject("QUOTE",ref,"Wedding cards"));assertEquals(MailPresentation.subject("ENQUIRY",ref,"Wedding cards"),MailPresentation.subject("INTAKE",ref,"Wedding cards"));assertEquals(MailPresentation.subject("QUOTE",ref,"Wedding cards"),MailPresentation.subject("DELIVERED",ref,"Wedding cards"));assertEquals("Verify your email address | J.D.Printex",MailPresentation.subject("VERIFY",null,null));}
}
